import{_ as t,o as i,c as a,a2 as l}from"./chunks/framework.CyZTVJbV.js";const m=JSON.parse('{"title":"kiwa test taxonomy — 各 lib 内 test 構成 SSOT","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/test-taxonomy.md","filePath":"concepts/test-taxonomy.md"}'),o={name:"concepts/test-taxonomy.md"};function s(d,e,r,c,n,p){return i(),a("div",null,[...e[0]||(e[0]=[l(`<h1 id="kiwa-test-taxonomy-—-各-lib-内-test-構成-ssot" tabindex="-1">kiwa test taxonomy — 各 lib 内 test 構成 SSOT <a class="header-anchor" href="#kiwa-test-taxonomy-—-各-lib-内-test-構成-ssot" aria-label="Permalink to &quot;kiwa test taxonomy — 各 lib 内 test 構成 SSOT&quot;">​</a></h1><p>kiwa monorepo 内の全 lib (<code>packages/*/</code>) が持つべき test の 5 分類 + dir 構成 + 各 test 契約を SSOT 化する。 本 doc の目的は <strong>「汎用大 tool で domain 精度を落とすのを避け、 各 lib 内に domain-specific test を書く」</strong> 方針を制度化することにある。</p><h2 id="前提思想" tabindex="-1">前提思想 <a class="header-anchor" href="#前提思想" aria-label="Permalink to &quot;前提思想&quot;">​</a></h2><ul><li><strong>汎用 tool は domain 精度に限界がある</strong>。 「速いか」 「メモリ使ってるか」 のような表層指標しか計測できない。</li><li><strong>domain 判断は各 lib 開発者の頭にある</strong>。 「cache lib は Redis PING 5 ms 以内」 「auth lib は OAuth callback 100 ms 以内」 「agent lib は skill X が tool Y を実際に呼ぶ」 等。</li><li><strong>共通 primitive は minimal に</strong>。 <code>perf-harness</code> = measure / regression / baseline のみ提供、 「何を測るべきか」 の domain 判断は各 lib の test に委ねる。</li><li><strong>未実装 lib は meta lint で検出</strong>。 test dir 存在チェッカーで PR gate、 実装漏れを構造的に防ぐ。</li></ul><h2 id="dir-構成-ssot" tabindex="-1">dir 構成 (SSOT) <a class="header-anchor" href="#dir-構成-ssot" aria-label="Permalink to &quot;dir 構成 (SSOT)&quot;">​</a></h2><p>各 lib は以下 5 dir 構成を持つ。 <code>unit</code> と <code>perf</code> は全 lib 必須、 残り 3 種は該当時のみ。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>packages/{lib}/tests/</span></span>
<span class="line"><span>├── unit/            # 関数単位 behavior test (全 lib 必須)</span></span>
<span class="line"><span>├── perf/            # p95 latency + memory (全 lib 必須)</span></span>
<span class="line"><span>├── fidelity/        # mock adapter vs real adapter 挙動一致 (mock 提供 lib のみ必須)</span></span>
<span class="line"><span>├── skill/           # skill 発火 assertion (skill 実装 lib のみ)</span></span>
<span class="line"><span>└── integration/     # 他 lib 連携 (依存関係ある lib のみ)</span></span></code></pre></div><p>現状 <code>packages/*/tests/</code> 直下に <code>*.test.ts</code> が並んでいる pkg は、 <code>unit/</code> サブ dir を新設して段階的に移行する。 <code>perf/</code> は既に 35 pkg で <code>tests/perf/</code> として運用中で、 本 SSOT と整合済。</p><h2 id="test-分類" tabindex="-1">test 分類 <a class="header-anchor" href="#test-分類" aria-label="Permalink to &quot;test 分類&quot;">​</a></h2><h3 id="unit-—-関数単位-behavior-test-全-lib-必須" tabindex="-1">unit — 関数単位 behavior test (全 lib 必須) <a class="header-anchor" href="#unit-—-関数単位-behavior-test-全-lib-必須" aria-label="Permalink to &quot;unit — 関数単位 behavior test (全 lib 必須)&quot;">​</a></h3><p><strong>目的</strong> = 関数の I/O behavior を検証する。 kiwa の base line、 全 lib で必須。</p><p><strong>契約</strong>。</p><ul><li>file 命名 = <code>*.test.ts</code> + <code>*.defensive.test.ts</code></li><li>実装 primitive = <code>vitest</code> の <code>describe</code> / <code>it</code> / <code>expect</code></li><li>判定基準 = test-passed marker 4 条件を全て満たすこと (<code>rules/quality.md § test-passed marker 発行前提</code> SSOT) <ol><li>本 PR diff の behavior test 追加あり</li><li>追加 test が変更箇所を実際に execute する</li><li>build success ≠ test 実行、 実行 log 貼付必須</li><li>層 0 (指示項目 check) 記載必須</li></ol></li></ul><p><strong>example</strong> = <code>packages/cache/tests/unit/redis-adapter.test.ts</code> で <code>cache.get(key)</code> が期待値返す assertion。</p><h3 id="perf-—-速度-memory-全-lib-必須" tabindex="-1">perf — 速度 + memory (全 lib 必須) <a class="header-anchor" href="#perf-—-速度-memory-全-lib-必須" aria-label="Permalink to &quot;perf — 速度 + memory (全 lib 必須)&quot;">​</a></h3><p><strong>目的</strong> = hot path の p95 latency + heap delta + concurrent throughput を計測、 baseline 比較で regression 検知。</p><p><strong>契約</strong>。</p><ul><li>file 命名 = <code>*.perf.ts</code></li><li>実装 primitive = <code>@kiwa-lab/perf-harness</code> の <code>runPerf3Layer()</code> (SSOT = <code>packages/perf-harness/README.md</code>)</li><li>baseline = <code>.perf-baseline/{lib}.json</code> に永続化、 <code>BaselineEnvelope</code> schema (env metadata 記録)</li><li>report = <code>docs/quality-reports/perf/saas/{lib}.md</code> に markdown 出力</li><li>判定基準 = 各 op が <code>serialP95CapMs</code> / <code>concurrentP95CapMs</code> / <code>memoryArrayBuffersCapBytes</code> を超えたら fail</li></ul><p><strong>example</strong> = <code>packages/cache/tests/perf/cache.perf.ts</code> で <code>redisEnvAccessor</code> が <code>serialP95CapMs: 5</code> 以内を assert。</p><p><strong>注意</strong> = perf test は test 実行時に混ざると <code>pnpm test</code> が遅くなる。 将来 <code>pnpm perf</code> script 分離を推奨 (現状は同一 script で走る)。</p><h3 id="fidelity-—-mock-↔-real-挙動一致-mock-提供-lib-のみ必須" tabindex="-1">fidelity — mock ↔ real 挙動一致 (mock 提供 lib のみ必須) <a class="header-anchor" href="#fidelity-—-mock-↔-real-挙動一致-mock-提供-lib-のみ必須" aria-label="Permalink to &quot;fidelity — mock ↔ real 挙動一致 (mock 提供 lib のみ必須)&quot;">​</a></h3><p><strong>目的</strong> = kiwa の各 lib が提供する mock adapter が、 real adapter (ioredis / real Redis / real Auth0 等) と同じ挙動を返すかを検証する。 mock を使う downstream test が real 環境で壊れる事故を防ぐ。</p><p><strong>契約</strong>。</p><ul><li>file 命名 = <code>*.fidelity.test.ts</code></li><li>実装 primitive = <code>@kiwa-lab/quality-metrics</code> の fidelity 軸 (現状 <code>ratio</code> 計算までは提供、 assertion 用 helper は要追加)</li><li>対象 = mock adapter を提供する全 lib (auth / cache / queue / search / ai-llm / realtime / storage 等)</li><li>判定基準 = mock method X 呼出結果と real method X 呼出結果が構造的に一致 (deep equal or schema match)</li><li>real 側は testcontainers / setup*Env で real backend 起動、 CI 環境で回す</li></ul><p><strong>example</strong> = <code>packages/cache/tests/fidelity/redis-fidelity.test.ts</code> で <code>mockRedis.set(&#39;k&#39;, &#39;v&#39;) → mockRedis.get(&#39;k&#39;)</code> と <code>realRedis.set(&#39;k&#39;, &#39;v&#39;) → realRedis.get(&#39;k&#39;)</code> の結果一致 assert。</p><p><strong>gap</strong> = 現状 kiwa には fidelity 用 primitive helper が薄い。 <code>@kiwa-lab/quality-metrics</code> の fidelity 軸 API を拡張して <code>assertFidelity(mockFn, realFn, cases)</code> を提供するのが次の課題。</p><h3 id="skill-—-skill-発火-assertion-skill-実装-lib-のみ" tabindex="-1">skill — skill 発火 assertion (skill 実装 lib のみ) <a class="header-anchor" href="#skill-—-skill-発火-assertion-skill-実装-lib-のみ" aria-label="Permalink to &quot;skill — skill 発火 assertion (skill 実装 lib のみ)&quot;">​</a></h3><p><strong>目的</strong> = skill / agent が想定 tool を <strong>実際に呼んだか</strong> を検証する。 「skill 定義した気でいたが実 code は tool 呼んでない」 型の silent fail を検出する。</p><p><strong>契約</strong>。</p><ul><li>file 命名 = <code>*.skill.test.ts</code></li><li>実装 primitive = 新規 <code>@kiwa-lab/skill-test</code> package (仮、 要新設)。 <code>assertToolCalled(agent, toolName)</code> / <code>assertSkillFlow(agent, expectedFlow)</code> 提供</li><li>対象 = skill / agent / tool 発火 logic を実装する lib (agent / mcp / cli / ai-llm 一部)</li><li>判定基準 = 想定 tool が呼ばれた回数 + 順序 + 引数が仕様通り</li></ul><p><strong>example</strong> = <code>packages/agent/tests/skill/reply-flow.skill.test.ts</code> で <code>agent.reply(input)</code> が <code>Read</code> tool を 1 回呼び、 その後 <code>Bash</code> tool を 0 回呼ぶ assertion。</p><p><strong>gap</strong> = 現状 kiwa に skill 発火 assertion 用 primitive なし。 <code>@kiwa-lab/skill-test</code> 新設が Q3 課題。</p><h3 id="integration-—-他-lib-連携-依存関係ある-lib-のみ" tabindex="-1">integration — 他 lib 連携 (依存関係ある lib のみ) <a class="header-anchor" href="#integration-—-他-lib-連携-依存関係ある-lib-のみ" aria-label="Permalink to &quot;integration — 他 lib 連携 (依存関係ある lib のみ)&quot;">​</a></h3><p><strong>目的</strong> = 複数 lib を実 import で組合せた end-to-end flow が動くか検証する。 mock 混ぜず real dependency で回す。</p><p><strong>契約</strong>。</p><ul><li>file 命名 = <code>*.integration.test.ts</code></li><li>実装 primitive = <code>vitest</code> + 各 lib の real setup</li><li>対象 = 他 lib に依存する lib (dapp × cache、 auth × ai-llm、 mcp × agent 等)</li><li>判定基準 = flow 通しの成功 + 副作用 (DB / cache / queue) の期待状態確認</li></ul><p><strong>example</strong> = <code>packages/dapp/tests/integration/dapp-cache-flow.integration.test.ts</code> で <code>dapp.connect() → cache.get() → dapp.persist()</code> 通しの動作 assert。</p><h2 id="test-分類別の必須判定" tabindex="-1">test 分類別の必須判定 <a class="header-anchor" href="#test-分類別の必須判定" aria-label="Permalink to &quot;test 分類別の必須判定&quot;">​</a></h2><table tabindex="0"><thead><tr><th>dir</th><th>対象 lib</th><th>必須判定</th></tr></thead><tbody><tr><td><code>unit/</code></td><td>全 lib</td><td>全 pkg 必須</td></tr><tr><td><code>perf/</code></td><td>全 lib</td><td>全 pkg 必須</td></tr><tr><td><code>fidelity/</code></td><td>mock 提供 lib</td><td>mock adapter 実装 lib のみ必須</td></tr><tr><td><code>skill/</code></td><td>skill 実装 lib</td><td>agent / mcp / cli / skill 定義 lib のみ必須</td></tr><tr><td><code>integration/</code></td><td>他 lib 依存 lib</td><td>依存関係のある lib のみ必須</td></tr></tbody></table><h2 id="meta-lint-q1、-本-ssot-準拠でチェック" tabindex="-1">meta lint (Q1、 本 SSOT 準拠でチェック) <a class="header-anchor" href="#meta-lint-q1、-本-ssot-準拠でチェック" aria-label="Permalink to &quot;meta lint (Q1、 本 SSOT 準拠でチェック)&quot;">​</a></h2><p>Q0 (本 SSOT) 準拠後、 meta lint tool を新設して以下を PR gate で強制する。</p><ul><li>各 lib に <code>unit/</code> + <code>perf/</code> が存在するか</li><li>mock adapter 提供 lib に <code>fidelity/</code> が存在するか</li><li>skill 実装 lib に <code>skill/</code> が存在するか</li><li>依存関係ある lib に <code>integration/</code> が存在するか</li></ul><p>不在なら PR block、 lib 開発者に強制する。 実装は <code>tests/release-smoke/tests/test-taxonomy-existence.test.ts</code> (存在 chk) + <code>scripts/kiwa-taxonomy-run.mjs</code> (実行 chk CLI、 Q5) の 2 経路。</p><h2 id="分類別実行-chk-cli-q5" tabindex="-1">分類別実行 chk CLI (Q5) <a class="header-anchor" href="#分類別実行-chk-cli-q5" aria-label="Permalink to &quot;分類別実行 chk CLI (Q5)&quot;">​</a></h2><p>meta lint (存在 chk) は 「file がある」 かのみ判定、 「file の中身が実行して pass するか」 は関与しない。 このため file 存在 = OK でも中身 broken の silent fail が起き得る。</p><p>Q5 = <code>scripts/kiwa-taxonomy-run.mjs</code> = 分類 (perf / fidelity / skill / integration) を指定して該当 lib 横断で vitest を実行 + lib × category の pass / fail matrix を出力する CLI。 meta lint (存在) + Q5 CLI (実行) の 2 軸で test-taxonomy meta 経路が完成する。</p><p>用法。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pnpm test:taxonomy -- --category fidelity</span></span>
<span class="line"><span>pnpm test:taxonomy -- --category skill --lib agent</span></span>
<span class="line"><span>pnpm test:taxonomy -- --category integration --format json</span></span>
<span class="line"><span>pnpm test:taxonomy -- --category fidelity --include-real   # Q6-5 real driver test 含む (KIWA_MODE=real auto)</span></span>
<span class="line"><span>pnpm test:taxonomy:all                                       # 4 分類 (perf/fidelity/skill/integration) 一括実行 + 統合 matrix</span></span></code></pre></div><ul><li><code>--category</code> = perf / fidelity / skill / integration / all のいずれか (必須) <ul><li><code>all</code> = 4 分類全実行 + 統合 matrix 出力、 1 分類でも fail で exit 1</li></ul></li><li><code>--lib</code> = 単一 lib 指定 (省略 = config 記載の該当 lib 全走査)</li><li><code>--format</code> = table (default) or json</li><li><code>--include-real</code> = <code>*.real.&lt;category&gt;.test.ts</code> (real driver test) を実行対象に含める、 KIWA_MODE=real env auto 注入 (Q6-5)</li><li>exit code = 0 (全 pass) / 1 (1 件でも fail / compile-fail / parse-fail / no-files / no-tests)</li><li><strong>no-files も fail 判定</strong> = CLI の目的は「揃ってる + 実行 pass」 の完全 chk、 file 不在で pass 扱いは意味を持たない。 config 記載 lib で該当分類 file 0 件 = 必ず exit 1 (flag なし)</li><li><strong>中身 chk 3 軸 (Q7)</strong> = 「file 揃ってる + 実行 pass」 に加えて質 gate を強制。 <ul><li><strong>insufficient-cases</strong> = category 別 minCases (perf 3 / fidelity 5 / skill 5 / integration 5) 未達で fail</li><li><strong>missing-assertion</strong> = it() block に <code>expect(...)</code> / <code>assertToolCalled</code> / <code>assertFidelity</code> 等の assertion 呼出なしで fail</li><li><strong>trivial-assertion</strong> = <code>expect(true).toBe(true)</code> / <code>expect(1).toBe(1)</code> / <code>expect(null).toBeNull()</code> 等の詐称 pattern を検出して fail</li><li>CLI 単独で 「file 有 + 実行 pass + 中身が空でない + trivial でない」 まで chk、 release-worthy 判定に近づく (但し coverage % / mutation MSI は別 gate、 domain-specific 中身の質は各 lib 開発者責務、 3 gate 統合運用が SSOT)</li></ul></li><li><strong>perf 分類特殊経路</strong> = perf は独自 config (<code>vitest.perf.config.ts</code>) 使用、 tsc compile 対象外 (<code>tests/perf/**/*</code> は <code>tsconfig.vitest.json</code> の exclude)、 CLI 側で <code>runPerfCell</code> に分岐して <code>vitest run -c vitest.perf.config.ts</code> 経路で実行する</li></ul><p><strong>real driver test SSOT</strong> (Q6)。 各 lib の <code>tests/fidelity/*.real.fidelity.test.ts</code> は mock adapter が real backend (testcontainers Redis / real Postgres / real BullMQ 等) 挙動を再現しているか動的検証する経路。 <code>resolveRealFidelityMode</code> primitive (<code>@kiwa-lab/quality-metrics</code>) で env-gate、 KIWA_MODE=real + 必須 env keys 全 set 時のみ実行、 default (未設定 or mock) は skip する opt-in 契約。 CLI 側 <code>--include-real</code> は Q6 exemplar (cache / queue / orm) を含めた matrix 実行の統一経路。</p><p>domain-specific test 中身の質 (case 網羅 / edge / coverage) は各 lib 開発者の責務、 meta lint + Q5 CLI の役割は 「test が正しく組立てられ実行して通っているか」 の構造的 gate に特化する (前提思想 = 汎用 tool で domain 精度は落ちるため domain 判断は各 lib に置く)。</p><h2 id="現状-gap-2026-07-13-時点" tabindex="-1">現状 gap (2026-07-13 時点) <a class="header-anchor" href="#現状-gap-2026-07-13-時点" aria-label="Permalink to &quot;現状 gap (2026-07-13 時点)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>dir</th><th>現状</th><th>gap</th></tr></thead><tbody><tr><td><code>unit/</code></td><td>全 pkg 完備 (直接 <code>tests/*.test.ts</code> として)</td><td>dir 分離は段階的、 現状の flat 構造は許容</td></tr><tr><td><code>perf/</code></td><td>35 pkg 完備 (<code>tests/perf/*.perf.ts</code>)</td><td>dir 名は既存整合、 gap なし</td></tr><tr><td><code>fidelity/</code></td><td>primitive 未整備</td><td><code>@kiwa-lab/quality-metrics</code> 拡張 + 各 lib 実装が必要</td></tr><tr><td><code>skill/</code></td><td>皆無</td><td><code>@kiwa-lab/skill-test</code> 新設 + skill 実装 lib への test 追加が必要</td></tr><tr><td><code>integration/</code></td><td>一部 (dapp / e2e) 存在、 命名バラバラ</td><td>命名統一 + 未実装 lib への追加が必要</td></tr></tbody></table><h2 id="進行順序" tabindex="-1">進行順序 <a class="header-anchor" href="#進行順序" aria-label="Permalink to &quot;進行順序&quot;">​</a></h2><ul><li><strong>Q0 (完了予定 = 本 doc)</strong> = test taxonomy SSOT 確定</li><li><strong>Q1</strong> = meta lint tool 新設 (<code>packages/test-existence-lint/</code>)、 Q0 準拠で dir 存在チェック</li><li><strong>Q2</strong> = 各 lib で不足 test dir を Q0 契約に沿って追加 (fidelity 系優先、 skill 系次)</li><li><strong>Q3</strong> = <code>packages/perf-harness/</code> を primitive のみに縮小 (three-layer / live / gate を各 lib 側の test に移す)</li><li><strong>Q4</strong> = <code>@kiwa-lab/skill-test</code> 新設 = skill 発火 assertion primitive</li></ul><p>各 Q は独立 PR。 Q1 は Q0 に依存、 Q2 は Q0 + fidelity primitive 拡張に依存、 Q3 は Q2 完遂後、 Q4 は Q0 完遂後。</p><h2 id="参照" tabindex="-1">参照 <a class="header-anchor" href="#参照" aria-label="Permalink to &quot;参照&quot;">​</a></h2><ul><li><code>rules/quality.md § test-passed marker 発行前提</code> = unit test の 4 条件 SSOT</li><li><code>packages/perf-harness/README.md</code> = perf test primitive の SSOT (精度契約 5 軸)</li><li><code>packages/quality-metrics/README.md</code> = fidelity / coverage / release gate SSOT</li></ul>`,58)])])}const b=t(o,[["render",s]]);export{m as __pageData,b as default};
